promptLocalized.zh:
{
  "type": "植物与营养信息图海报",
  "subject": {
    "name": "{argument name=\"subject name\" default=\"灵芝\"}",
    "scientific_name": "{argument name=\"scientific name\" default=\"Ganoderma lucidum\"}",
    "image": "大型、细节丰富的插图，展示了一朵带有同心生长环的红褐色光泽灵芝，位于顶部中央"
  },
  "layout": {
    "style": "简洁、现代、网格化，浅米色背景配以细微的网格线、极简图标及数据可视化元素",
    "sections": [
      {
        "title": "页眉/简介 (左上)",
        "content": "大标题文字、学名、标签（'多孔菌科·灵芝属', '药食同源'）、简短描述文字、产地分布图（中国/东亚）以及季节性时间轴柱状图。"
      },
      {
        "title": "1 营养成分详解 (每 100g) (右上)",
        "content": "营养成分分解。包括显示热量（295 kcal）的环形图、宏量营养素（蛋白质、碳水化合物、脂肪等）百分比表格、维生素和矿物质的双柱状图，以及 GI 指数滑块（值为 15）。"
      },
      {
        "title": "2 健康功效地图 (中左)",
        "content": "健康功效地图。特色人体轮廓图，带有 6 个标注点，连接到图标和文字块，描述其功效（如免疫调节、抗衰老、护肝、助眠、调节血糖/血脂、肿瘤辅助治疗），每项均配有 5 星评分。"
      },
      {
        "title": "3 烹饪方法矩阵 (中中)",
        "content": "烹饪方法矩阵。3x3 的 9 个图标网格，代表不同的处理方式（煮、炖、泡茶、煮粥、蒸、炒、泡酒、研粉、烤、凉拌）。每项包含温度/时间、营养保留百分比及星级评分。"
      },
      {
        "title": "4 四季食用指南 (中右)",
        "content": "四季食用指南。围绕中心灵芝图标分为四个象限（春、夏、秋、冬）的圆形图，详细说明季节性益处及最佳食用期（7-10 个月）。"
      },
      {
        "title": "5 黄金搭配矩阵 (下左)",
        "content": "黄金搭配矩阵。3x3 网格，展示围绕中心灵芝的 8 种互补食材（枸杞、红枣、黄芪、银耳、山药、莲子、桂圆、陈皮），并附有解释协同效应的文字。"
      },
      {
        "title": "6 适宜人群画像 (下中)",
        "content": "适宜人群画像。针对 7 类用户群体（儿童、孕妇、老年人、运动员、亚健康人群、免疫力低下者、高血压患者）的图标和文字，展示建议每日摄入量及星级评分。"
      },
      {
        "title": "7 禁忌与注意事项 (下右)",
        "content": "禁忌与注意事项。列表格式，配有警告图标，涵盖不适宜人群、过敏警告、药物相互作用及每日最大摄入量建议。"
      },
      {
        "title": "8 选购与储存指南 (下左，第 5 部分下方)",
        "content": "选购与储存指南。包含新鲜度核对清单、质量等级表（特级、一级、二级、三级）及星级评分、储存条件图标（温度、湿度、保质期）以及保质期时间轴。"
      },
      {
        "title": "9 趣味知识扩展 (下右，第 7 部分下方)",
        "content": "趣味知识扩展。文字块涵盖历史传说、别名、全球产量数据（5 万吨，中国占 85%）及可持续性评分（A 级）。"
      }
    ]
  }
}

