promptLocalized.zh:
{
  "type": "四格竖版漫画",
  "style": "{argument name=\"art style\" default=\"黑白铅笔素描，交叉排线阴影，讽刺漫画风格\"}",
  "characters": {
    "subject_1": "{argument name=\"main character\" default=\"Sam Altman\"}，卷发，休闲毛衣",
    "subject_2": "{argument name=\"interviewer\" default=\"Ronan Farrow\"}，西装，领带，手持记事本"
  },
  "layout": {
    "panels": [
      {
        "panel_number": 1,
        "top_caption": "SAM ALTMAN 以为这会是一篇不错的简短人物专访……",
        "scene": "subject_1 双手交叉呈塔状，神情自鸣得意；subject_2 神情严肃地做着记录。",
        "thought_bubble": "我会表现得很迷人。这会是一篇很棒的人物特写。大家都会喜欢的。",
        "center_text": "RONAN FARROW 的采访",
        "inset_portraits": {
          "count": 2,
          "labels": ["HARVEY WEINSTEIN 丑闻曝光", "LESLIE MOONVES 丑闻曝光"]
        },
        "info_boxes": {
          "count": 3,
          "text": [
            "RONAN FARROW：普利策奖得主，曾为《纽约客》揭露 HARVEY WEINSTEIN 的罪行",
            "以及 CBS 的 LESLIE MOONVES。",
            "权力。滥用。问责。"
          ]
        }
      },
      {
        "panel_number": 2,
        "top_caption": "画面切至……",
        "scene": "subject_1 的特写，神情震惊且惊恐。",
        "article_header": "{argument name=\"publication\" default=\"《纽约客》\"}\nSAM ALTMAN 人物专访\nOPENAI CEO 复杂的探索之旅\n作者：Ronan Farrow"
      },
      {
        "panel_number": 3,
        "top_caption": "文章发表后不久……",
        "scene": "subject_1 看起来压力巨大，满头大汗，正把手机贴在耳边。周围有 6 只手拿着智能手机。",
        "phone_labels": ["风投", "记者", "前员工", "投资者", "科技公司 CEO", "前同事"],
        "shouts": {
          "count": 8,
          "text": [
            "{argument name=\"main accusation\" default=\"骗子\"}!",
            "撒谎成性！",
            "病态谎言！",
            "你根本停不下来！",
            "骗子！！！",
            "反社会人格！（据称）",
            "他说的每一句话都是谎言！",
            "操纵人心的骗子！"
          ]
        },
        "sound_effects": "铃！铃！铃！"
      },
      {
        "panel_number": 4,
        "top_caption": "报道总结道……",
        "scene": "subject_1 看起来彻底崩溃且沮丧。",
        "quote_box": "\"ALTMAN 频繁且一贯地欺骗投资者、员工、项目，甚至是亲密朋友。\"\n\"他似乎对撒谎毫无心理负担。\"\n\"据多人描述，他是一个撒谎成性的人和反社会者。\"\n（据称）",
        "thought_bubble": {
          "scene": "快乐的 subject_1 手持印有“世界最佳 CEO”的马克杯。",
          "text": "我以为这会是一篇不错的简短人物专访……",
          "sparkle_words": {
            "count": 4,
            "text": ["天才！", "远见卓识！", "鼓舞人心！", "杰出的领导者！"]
          }
        },
        "bottom_caption": "结果，这篇专访彻底揭穿了他。"
      }
    ]
  }
}

