promptLocalized.zh:
{
  "type": "manga page",
  "style": "anime illustration, full color",
  "characters": {
    "woman": {
      "appearance": "长 {argument name=\"hair color\" default=\"黑色\"} 头发，紫色眼睛",
      "outfit": "{argument name=\"shirt color\" default=\"灰色\"} 长袖衬衫，深灰色紧身牛仔裤，赤脚"
    },
    "delivery_man": {
      "appearance": "秃头，年长男性，浓眉",
      "outfit": "蓝色工作夹克，内搭灰色衬衫"
    }
  },
  "layout": {
    "description": "页面垂直分割。左侧包含 4 个堆叠的横向分镜。右侧是一个高大的纵向分镜。",
    "left_column_panels": [
      {
        "panel_number": 1,
        "scene": "女性坐在客厅的灰色沙发上，手里拿着一个白色马克杯。",
        "text_elements": [
          { "type": "speech_bubble", "text": "？" },
          { "type": "sound_effect", "text": "叮咚♪", "description": "门铃声" }
        ]
      },
      {
        "panel_number": 2,
        "scene": "女性打开前门。快递员站在门外，手里拿着一个纸箱，面带微笑。",
        "text_elements": [
          { "type": "speech_bubble", "speaker": "delivery_man", "text": "{argument name=\"delivery greeting\" default=\"您好〜！快递来啦！\"}" },
          { "type": "speech_bubble", "speaker": "woman", "text": "啊，好的……谢谢" }
        ]
      },
      {
        "panel_number": 3,
        "scene": "快递员热情大笑的特写，背景是闪闪发光的粉色。",
        "text_elements": [
          { "type": "speech_bubble", "speaker": "delivery_man", "text": "{argument name=\"creepy compliment\" default=\"哎呀〜？哎呀呀，真是位大美人啊！像您这么漂亮的人独自居住，真是太可惜了呢〜♪\"}" }
        ]
      },
      {
        "panel_number": 4,
        "scene": "女性感到厌恶和不适的特写，微微冒汗。前景可见快递员的后脑勺。",
        "text_elements": [
          { "type": "speech_bubble", "speaker": "delivery_man", "text": "话说回来，您的皮肤真好！身材也超棒的〜简直像模特一样！" },
          { "type": "thought_bubble", "speaker": "woman", "text": "{argument name=\"woman reaction\" default=\"诶……？这人是谁啊……感觉有点恶心……\"}" },
          { "type": "caption_box", "text": "此后，快递员依然在喋喋不休地夸赞着……" }
        ]
      }
    ],
    "right_column_panel": {
      "panel_number": 5,
      "scene": "女性全身肖像，站在室内，双臂交叉，神情恼怒且充满怀疑。",
      "text_elements": [
        { "type": "thought_bubble", "speaker": "woman", "text": "到底是谁啊……？" }
      ]
    }
  }
}

