{
  "image_prompt": {
  "subject": {
  "description": "一幅超现实视觉错觉肖像，将两种视角融合在同一张脸孔上。",
  "demographics": "男性，非洲裔。",
  "hair": "光头（剃光），下巴和下颌线处有短而有质感的胡茬。",
  "expression": "表情冷静克制，目光深邃直视前方，嘴部表情中性。"
  },
  "optical_illusion_structure": {
  "concept": "正面和侧面视角同时存在（以立体主义概念呈现，但采用写实摄影级渲染）。",
  "morphology": "脸部右侧（鼻子、嘴唇、额头、下巴）在背景中形成清晰锐利的侧面轮廓；左侧（耳朵、脸颊）呈现正面视角。头部顶部拉长并逐渐变窄，呈圆锥状，以适应视角转换。",
  "eye_placement": "正面平面上仅有一只写实的眼睛直视观众，而下方的鼻子和嘴巴旋转了 90 度，呈侧向。"
  },
  "details_and_texture": {
  "skin": "超写实皮肤纹理，可见毛孔、皮肤纹理以及眼周和嘴周的细微皱纹。",
  "facial_hair": "下巴和鬓角区域有高度细腻的胡茬纹理。",
  "accessories": "可见的左耳佩戴着一枚银色小圆环耳环。"
  },
  "clothing": {
  "outfit": "简约的深色圆领上衣或毛衣，在左下角隐约可见，为颈部提供深色基底。",
  "color": "黑色或深灰色。"
  },
  "style_and_medium": {
  "art_style": "超现实主义摄影，写实数字图像处理，心理视觉错觉。",
  "color_palette": "黑白单色（灰度）。",
  "aesthetic": "高对比度，锐利且前卫，让人联想到毕加索的双视角构图，但具备真实的摄影质感。"
  },
  "lighting_and_environment": {
  "lighting_setup": "摄影棚级高对比度布光（明暗对照法）。额头、颧骨和鼻梁处有明亮的高光；脸部侧面和颈部融入深沉浓重的阴影中，以增强结构塑造感。",
  "background": "纯白或极浅的灰色背景，营造强烈的负空间，以突出侧面轮廓。"
  },
  "composition": {
  "framing": "特写肖像构图，整体居中，但由于错觉结构呈现非对称性。头部与肩部肖像。",
  "text_overlay_reference": "顶部留白。（注：原图顶部边缘有文字“Cette Photo est incroyable”）。"
  },
  "technical_specs": {
  "camera": "人像镜头（例如 85mm），精准对焦于眼睛。",
  "quality": "8K 分辨率，极致细节，大师级锐度品质。"
  }
  }
}

